ours = iter([("T1", 39000), ("T2", 12500), ("T3", 8000), ("T6", 2000)])
psp  = iter([("T1", 39000), ("T2", 12000), ("T4", 4400), ("T6", 2000)])
a, b = next(ours, None), next(psp, None)
while a or b:
    if b is None or (a and a[0] < b[0]):
        print(a[0], "상대 파일에 없음", a[1]); a = next(ours, None)
    elif a is None or b[0] < a[0]:
        print(b[0], "우리 원장에 없음", b[1]); b = next(psp, None)
    else:
        print(a[0], "일치" if a[1] == b[1] else f"금액 다름 {a[1]} vs {b[1]}")
        a, b = next(ours, None), next(psp, None)
